const date = new Date().toISOString().slice(0,10);
const all = $input.all().map(i => i.json);

// chat для авто-бекапу о 03:00 (група Business Atlas)
const ADMIN_CHAT_ID = '8760700059';

let chatId = ADMIN_CHAT_ID;
let source = 'scheduled';
try {
  const tg = $('Telegram /backup Command Trigger').first();
  const cid = tg && tg.json && tg.json.message && tg.json.message.chat && tg.json.message.chat.id;
  if (cid) { chatId = cid; source = 'manual'; }
} catch (e) {}

return [{ json: {
  filePath: `backups/${date}/workflows.json`,
  fileContent: JSON.stringify(all, null, 2),
  count: all.length,
  date,
  chatId,
  source
} }];

const date = new Date().toISOString().slice(0, 10);
const all = $input.all().map(i => i.json);

// Chat ID cho auto-backup
const ADMIN_CHAT_ID = '8760700059';
let chatId = ADMIN_CHAT_ID;
let source = 'scheduled';

try {
  const tg = $('Telegram /backup Command Trigger').first();
  const cid = tg && tg.json && tg.json.message && tg.json.message.chat && tg.json.message.chat.id;
  if (cid) {
    chatId = cid;
    source = 'manual';
  }
} catch (e) {}

// Chuyển từng workflow thành chuỗi JSON nguyên bản
return $input.all().map(item => {
  const workflowData = item.json;
  const safeName = (workflowData.name || 'workflow').replace(/[^a-zA-Z0-9]/g, '_');

  return {
    json: {
      fileName: `${safeName}.json`,
      filePath: `backups/${safeName}.json`,
      fileContent: JSON.stringify(workflowData, null, 2), // Đã thêm dấu phẩy chuẩn cú pháp
      workflowData,
      count: all.length,
      date,
      chatId,
      source
    }
  };
});

